# -*- coding: utf-8 -*-
"""只读诊断：登录金猫(JMSM)看 平台订单>未发货 列表结构。
- dump 表头列、每单订单号+各列值(找快递方/渠道列)、筛选控件。
- 绝不点击 批量发货 / 批量修改快递方，纯读取 + 截图。
输出：capture/dumps/wms_diag_jmsm.txt / .png / .html
用法：python capture/wms_diag_jmsm.py
"""
import sys, os, time, json
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import config, secrets
from playwright.sync_api import sync_playwright

LOGIN_URL = "http://193.112.93.60:9999/login.html"
ORDERINFO = "http://193.112.93.60:9999/orderInfo/page/orderInfo.html"
ACC = next(a for a in secrets.WMS_ACCOUNTS if a["login"] == "JMSM")  # 金猫

OUT = os.path.join(config.DUMP_DIR, "wms_diag_jmsm.txt")
lines = []
def w(s=""):
    lines.append(str(s))


def main():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True, args=["--no-sandbox"])
        ctx = browser.new_context(ignore_https_errors=True)
        page = ctx.new_page()
        for _ in range(5):
            try:
                page.goto(LOGIN_URL, wait_until="domcontentloaded", timeout=30000); break
            except Exception: time.sleep(2)
        time.sleep(1.5)
        page.fill("#loginName", ACC["login"]); page.fill("#loginPwd", ACC["password"]); page.click("#loginSubmit")
        time.sleep(5)
        w(f"login url: {page.url}")

        page.goto(ORDERINFO, wait_until="domcontentloaded", timeout=40000)
        time.sleep(5)
        # 点一次查询刷新未发货
        try:
            page.click("button:has-text('查询')", timeout=5000); time.sleep(3)
        except Exception as e:
            w(f"点查询失败: {e}")

        # 未发货数
        el = page.query_selector(".el-pagination__total")
        w(f"分页总数文本: {el.inner_text().strip() if el else '(无)'}")

        # ---- 筛选控件：搜索区的 label + placeholder + select 选中值 ----
        w("\n==== 筛选控件(搜索区) ====")
        controls = page.evaluate(r"""() => {
            const out = [];
            document.querySelectorAll('.el-form-item, .el-input, .el-select').forEach(g=>{
              const lab = g.querySelector('.el-form-item__label');
              const inp = g.querySelector('input');
              const vis = !!(g.offsetWidth||g.offsetHeight);
              if(!vis) return;
              out.push({
                label: lab ? lab.innerText.trim() : '',
                placeholder: inp ? (inp.getAttribute('placeholder')||'') : '',
                value: inp ? (inp.value||'') : ''
              });
            });
            return out;
        }""")
        seen=set()
        for c in controls:
            key = (c['label'], c['placeholder'])
            if key in seen: continue
            seen.add(key)
            if c['label'] or c['placeholder']:
                w(f"  label={c['label']!r} placeholder={c['placeholder']!r} value={c['value']!r}")

        # ---- 表头 ----
        w("\n==== 表头列(主表) ====")
        heads = page.evaluate(r"""() => {
            const hw = document.querySelector('.el-table__header-wrapper');
            if(!hw) return [];
            return [...hw.querySelectorAll('thead th')].map(th=>th.innerText.trim());
        }""")
        for i,h in enumerate(heads):
            w(f"  [{i}] {h!r}")

        # ---- 每行：按表头列对齐取值 ----
        w("\n==== 未发货订单行(主表 body，按列对齐) ====")
        rows = page.evaluate(r"""() => {
            const bw = document.querySelector('.el-table__body-wrapper');
            if(!bw) return [];
            return [...bw.querySelectorAll('tr.el-table__row')].map(tr=>{
              return [...tr.querySelectorAll('td')].map(td=>td.innerText.replace(/\s+/g,' ').trim());
            });
        }""")
        w(f"(主表 body 行数={len(rows)})")
        for r in rows:
            w("  ---")
            for i,cell in enumerate(r):
                head = heads[i] if i < len(heads) else f"col{i}"
                if cell:
                    w(f"    {head}: {cell}")

        # 截图 + html
        page.screenshot(path=os.path.join(config.DUMP_DIR, "wms_diag_jmsm.png"), full_page=True)
        html = page.content()
        with open(os.path.join(config.DUMP_DIR, "wms_diag_jmsm.html"), "w", encoding="utf-8") as f:
            f.write(html)
        w(f"\nhtml bytes={len(html)}  url={page.url}")

        with open(OUT, "w", encoding="utf-8") as f:
            f.write("\n".join(lines))
        print("WROTE", OUT)
        browser.close()


if __name__ == "__main__":
    main()

# -*- coding: utf-8 -*-
"""只读：按平台订单号查金猫这批单的当前状态/快递方/跟踪号，判断真跑到底发出去没有。
清掉'未发货'状态筛选后逐个查询。绝不发货。输出 capture/dumps/wms_lookup_orders.txt
"""
import sys, os, time
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import config, secrets
from playwright.sync_api import sync_playwright

LOGIN_URL = "http://193.112.93.60:9999/login.html"
ORDERINFO = "http://193.112.93.60:9999/orderInfo/page/orderInfo.html"
ACC = next(a for a in secrets.WMS_ACCOUNTS if a["login"] == "JMSM")

ORDERS = ['P2AD6TCD61635','P2AD6TCD61623','P2AD6TCD61606','P2AD6TCD61637','PO700005936',
          'P2AC6TCD61506','P2AC6TCD61481','P2AC6TCD61471','P2AC6TCD61470','P2AC6TCD61469']

OUT = os.path.join(config.DUMP_DIR, "wms_lookup_orders.txt")
lines = []
def w(s=""): lines.append(str(s))


def read_rows(page):
    """读主表 body 每行按列对齐的关键字段。"""
    return page.evaluate(r"""() => {
        const hw = document.querySelector('.el-table__header-wrapper');
        const heads = hw ? [...hw.querySelectorAll('thead th')].map(t=>t.innerText.trim()) : [];
        const bw = document.querySelector('.el-table__body-wrapper');
        const rows = bw ? [...bw.querySelectorAll('tr.el-table__row')].map(tr=>{
            const o={}; [...tr.querySelectorAll('td')].forEach((td,i)=>{o[heads[i]||('c'+i)]=td.innerText.replace(/\s+/g,' ').trim();}); return o;
        }) : [];
        return {heads, rows};
    }""")


def clear_status_filter(page):
    """清掉 订单状态='未发货' 使查询覆盖全部状态。hover 出清除叉并点。"""
    try:
        # 找到 placeholder=订单状态 的 input 所在 el-select
        box = page.query_selector("xpath=//input[@placeholder='订单状态']/ancestor::div[contains(@class,'el-select')][1]")
        if not box:
            w("未定位到 订单状态 select"); return
        box.hover(); time.sleep(0.5)
        x = box.query_selector("i.el-icon-circle-close, i.el-select__caret.el-icon-circle-close")
        if x and x.is_visible():
            x.click(); time.sleep(0.5); w("已点清除叉清空 订单状态")
        else:
            # 退而求其次：打开下拉选 '全部'
            box.click(); time.sleep(0.6)
            for el in page.query_selector_all(".el-select-dropdown__item"):
                if el.is_visible() and (el.inner_text() or "").strip() in ("全部",""):
                    el.click(); w("下拉选 全部"); break
    except Exception as e:
        w(f"清状态筛选异常: {e}")


def main():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=True, args=["--no-sandbox"])
        ctx = browser.new_context(ignore_https_errors=True); page = ctx.new_page()
        for _ in range(5):
            try: page.goto(LOGIN_URL, wait_until="domcontentloaded", timeout=30000); break
            except Exception: time.sleep(2)
        time.sleep(1.5)
        page.fill("#loginName", ACC["login"]); page.fill("#loginPwd", ACC["password"]); page.click("#loginSubmit")
        time.sleep(5)
        page.goto(ORDERINFO, wait_until="domcontentloaded", timeout=40000); time.sleep(5)

        clear_status_filter(page)

        for od in ORDERS:
            try:
                inp = page.query_selector("input[placeholder='平台订单号']")
                inp.fill(""); inp.fill(od); time.sleep(0.3)
                page.click("button:has-text('查询')"); time.sleep(2.5)
                data = read_rows(page)
                rows = data["rows"]
                w(f"\n==== {od} ====")
                if not rows:
                    w("  (查无此单/或不在可见结果)")
                for r in rows:
                    st = r.get('订单状态') or r.get('c1') or ''
                    # 表头里没有'订单状态'列名时，整行打印关键列
                    w(f"  平台订单号={r.get('平台订单号','')} 快递方={r.get('快递方','')} "
                      f"跟踪单号={r.get('跟踪单号','')} 同步平台状态={r.get('同步平台状态','')}")
                    # 整行兜底
                    w(f"    (整行) { {k:v for k,v in r.items() if v} }")
            except Exception as e:
                w(f"\n==== {od} ====\n  查询异常: {e}")

        with open(OUT, "w", encoding="utf-8") as f: f.write("\n".join(lines))
        print("WROTE", OUT)
        browser.close()


if __name__ == "__main__":
    main()

# -*- coding: utf-8 -*-
"""
WMS（海外仓）操作：一件代发 > 平台订单
流程：筛选未发货 -> 全选 -> 批量修改快递方(按店铺优先级，从上往下) -> 批量发货
      每个快递方发一轮，失败的留在"未发货"，下一个快递方再发（实现"依次往下试"）。
DRY_RUN=True 时不真正点击"确认/批量发货"，只记录将要执行的动作。
"""
import time
import config, core
from core import log, ORDERINFO_WMS
from rules import courier_priority, ALL_COURIERS


def open_platform_orders(page):
    core.safe_goto(page, ORDERINFO_WMS)
    time.sleep(4)


def count_rows(page):
    """未发货订单数。优先读分页 '共 N 条'（el-table 固定列会使 .el-table__row 翻倍，不能直接数行）。"""
    import re
    el = page.query_selector(".el-pagination__total")
    if el:
        m = re.findall(r"\d+", el.inner_text() or "")
        if m:
            return int(m[0])
    rows = page.query_selector_all(".el-table__row")
    return len(rows) // 2 if rows else 0


def close_tips(page, rounds=4):
    """关闭所有可见 el-message-box / Tip（点 ok/确定/关闭），返回文本列表。"""
    texts = []
    for _ in range(rounds):
        box = page.query_selector(".el-message-box__wrapper:visible .el-message-box")
        if not box:
            break
        try:
            texts.append((box.inner_text() or "").strip()[:120])
        except Exception:
            pass
        done = False
        for t in ["ok", "OK", "确定", "确认", "关闭", "知道了"]:
            b = page.query_selector(f".el-message-box__wrapper:visible button:has-text('{t}')")
            if b and b.is_visible():
                try: b.click(); done = True
                except Exception: pass
                break
        if not done:
            try: page.keyboard.press("Escape")
            except Exception: pass
        time.sleep(1)
    return texts


def ensure_unshipped_filter(page):
    """确保状态筛选为'未发货'并查询。页面默认即为未发货，这里点一次查询刷新。"""
    try:
        page.click("button:has-text('查询')", timeout=5000)
        time.sleep(3)
    except Exception as e:
        log(f"[WMS] 点击查询失败: {e}")


def select_all(page):
    """勾选表头全选框。无数据时该框禁用，返回 False。"""
    header_cb = page.query_selector(".el-table__header-wrapper .el-checkbox, .el-table__header .el-checkbox")
    if not header_cb:
        return False
    cls = header_cb.get_attribute("class") or ""
    if "is-disabled" in cls:
        return False
    try:
        header_cb.click()
        time.sleep(1)
        return True
    except Exception as e:
        log(f"[WMS] 全选失败: {e}")
        return False


def set_courier(page, courier):
    """打开'批量修改快递方'弹窗，选择 courier，确认。DRY_RUN 下不点确认。"""
    try:
        page.click("button:has-text('批量修改快递方')", timeout=6000)
    except Exception as e:
        log(f"[WMS] 打开'批量修改快递方'失败: {e}")
        return False
    time.sleep(1.5)
    # 可见弹窗(:visible)内的 快递方 下拉（页面存在多个隐藏 el-dialog，必须限定可见）
    try:
        page.click(".el-dialog:visible .el-select", timeout=4000)
        time.sleep(1)
        opt = None
        for el in page.query_selector_all(".el-select-dropdown__item"):
            if el.is_visible() and (el.inner_text() or "").strip() == courier:
                opt = el; break
        if not opt:
            log(f"[WMS] 未找到快递方选项 {courier}")
            _close_dialog(page)
            return False
        opt.click()
        time.sleep(0.5)
    except Exception as e:
        log(f"[WMS] 选择快递方 {courier} 失败: {e}")
        _close_dialog(page)
        return False

    if config.DRY_RUN:
        log(f"[WMS][DRY] 将设置快递方 = {courier}（跳过'确认'）")
        _close_dialog(page)
        return True
    try:
        # 确认按钮：可见弹窗内的 primary 按钮（文本'确认'，与'取消'区分）
        ok = page.query_selector(".el-dialog:visible button.el-button--primary")
        if not ok:
            for b in page.query_selector_all(".el-dialog:visible button"):
                if (b.inner_text() or "").replace(" ", "") in ("确认", "确定"):
                    ok = b; break
        if not ok:
            log("[WMS] 未找到可见确认按钮"); return False
        ok.click()
        time.sleep(2)
        tips = close_tips(page)   # 关掉"成功"Tip，否则挡住后续批量发货
        log(f"[WMS] 已设置快递方 = {courier}  Tip={tips}")
        return True
    except Exception as e:
        log(f"[WMS] 确认快递方失败: {e}")
        return False


def _close_dialog(page):
    try:
        page.click(".el-dialog button:has-text('取消')", timeout=2000)
    except Exception:
        try:
            page.keyboard.press("Escape")
        except Exception:
            pass
    time.sleep(0.5)


def batch_ship(page):
    """点击'批量发货'，处理'预发货成功'提示。DRY_RUN 下不执行。"""
    if config.DRY_RUN:
        log("[WMS][DRY] 将点击'批量发货'（已跳过）")
        return True
    try:
        page.click("button:has-text('批量发货')", timeout=6000)
        time.sleep(2)
        # 可能的二次确认（限可见弹窗）
        for t in ["确定", "确认", "ok", "OK"]:
            b = page.query_selector(f".el-message-box__wrapper:visible button:has-text('{t}'), .el-dialog:visible button:has-text('{t}')")
            if b and b.is_visible():
                try: b.click(); time.sleep(1.5)
                except Exception: pass
                break
        time.sleep(2)
        tips = close_tips(page)   # 捕获并关闭 'Tip: 预发货成功'
        ok = any("预发货成功" in t or "成功" in t for t in tips)
        log(f"[WMS] 已执行批量发货  结果Tip={tips}")
        return ok if tips else True
    except Exception as e:
        log(f"[WMS] 批量发货失败: {e}")
        return False


def read_order_numbers(page):
    """读当前未发货列表的平台订单号（去重）。订单号形如 P2AC6TCD61443。"""
    try:
        nums = page.evaluate(r"""() => {
            const s=new Set();
            document.querySelectorAll('.el-table__row').forEach(r=>{
                const m=(r.innerText||'').match(/P[0-9A-Z]{9,15}/g); if(m) m.forEach(x=>s.add(x));
            });
            return [...s];
        }""")
        return nums or []
    except Exception:
        return []


def process_shop(page, account, already_logged_in=False):
    """处理单个店铺：按快递方优先级逐轮发货。返回 {shop, before, left, left_orders}。"""
    priority = courier_priority(account["login"])
    log(f"[WMS] === 处理店铺 {account['shop']}（{account['login']}），快递方优先级 {priority} ===")
    if not already_logged_in and not core.wms_login(page, account):
        log(f"[WMS] {account['shop']} 登录失败，跳过")
        return {"shop": account["shop"], "error": "登录失败", "left_orders": []}
    open_platform_orders(page)
    ensure_unshipped_filter(page)

    total_before = count_rows(page)
    log(f"[WMS] {account['shop']} 未发货订单 ≈ {total_before} 条")
    if total_before == 0:
        log(f"[WMS] {account['shop']} 无未发货订单")
        return {"shop": account["shop"], "before": 0, "left": 0, "left_orders": []}

    limit = config.MAX_ORDERS_PER_RUN
    for courier in priority:
        open_platform_orders(page)
        ensure_unshipped_filter(page)
        remaining = count_rows(page)
        if remaining == 0:
            log(f"[WMS] {account['shop']} 已全部发出")
            break
        if limit and remaining > limit:
            log(f"[WMS][安全] 未发货 {remaining} > 单次上限 {limit}，建议调大 MAX_ORDERS_PER_RUN 或分批。")
        log(f"[WMS] 用快递方 [{courier}] 处理剩余 {remaining} 条")
        if not select_all(page):
            log("[WMS] 无法全选（可能无数据/禁用）"); break
        if not set_courier(page, courier):
            continue
        # 改快递方后列表会刷新、丢失勾选，发货前重新全选
        if not select_all(page):
            log("[WMS] 改快递方后重新全选失败，跳过本轮发货"); continue
        batch_ship(page)
        time.sleep(2)
        # 本轮结束后重新计数，记录该快递方实际发出多少
        after = count_rows(page)
        shipped = max(0, remaining - after)
        core.log.event("WMS批量发货", shop=account["shop"], account=account["login"],
                       courier=courier, before_round=remaining, shipped=shipped, left_round=after)

    open_platform_orders(page)
    ensure_unshipped_filter(page)
    left = count_rows(page)
    left_orders = read_order_numbers(page) if left else []
    dry = "（DRY_RUN 未真正发货）" if config.DRY_RUN else ""
    log(f"[WMS] {account['shop']} 处理完成，仍未发货 ≈ {left} 条{dry}")
    if left and not config.DRY_RUN:
        log(f"[WMS] ⚠️ {account['shop']} 试完所有快递方仍未发货：{left_orders}")
    core.log.event("WMS发货汇总", shop=account["shop"], account=account["login"],
                   before=total_before, shipped=max(0, total_before - left),
                   left=left, left_orders=left_orders)
    return {"shop": account["shop"], "before": total_before, "left": left, "left_orders": left_orders}

